21	// addControlPlaneFlags registers the persistent flags shared by every
22	// control-plane command group. Persistent so they're inherited by nested
23	// subcommands (e.g. `entire repo mirror list`):
24	//   - --json: emit the raw wire JSON instead of the default human table.
25	//   - --insecure-http-auth: permit the token exchange over plain http://
26	//     (local/dev deployments where the core isn't behind TLS). Hidden, as
27	//     elsewhere in the CLI.
28	func addControlPlaneFlags(cmd *cobra.Command) {
29		cmd.PersistentFlags().Bool("json", false, "Output raw JSON instead of a table")
30		cmd.PersistentFlags().Bool("insecure-http-auth", false, "Allow authentication over plain HTTP (insecure, for local development only)")
31		if err := cmd.PersistentFlags().MarkHidden("insecure-http-auth"); err != nil {
32			panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
33		}
34	}
