230	// tableStyles holds the foreground styles for the human table/field views,
231	// matching the activity/session palette: gray ("8") for headers and
232	// secondary cells, white ("7") for the primary (first-column) value. When
233	// color is disabled (non-TTY, NO_COLOR — e.g. piped output and tests) the
234	// styles are no-ops and output is plain.
235	type tableStyles struct {
236		enabled bool
237		header  lipgloss.Style
238		primary lipgloss.Style
239		cell    lipgloss.Style
240	}
241	
242	func newTableStyles(w io.Writer) tableStyles {
243		if !shouldUseColor(w) {
244			return tableStyles{}
245		}
246		return tableStyles{
247			enabled: true,
248			header:  lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted)).Bold(true),
249			primary: lipgloss.NewStyle(), // default fg: inverts with terminal theme
250			cell:    lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted)),
251		}
252	}
253	
254	// style applies s to text only when color is enabled; otherwise it returns
255	// text unchanged so padding math and plain output stay correct.
256	func (t tableStyles) style(s lipgloss.Style, text string) string {
257		if !t.enabled {
258			return text
259		}
260		return s.Render(text)
261	}
262	
263	// columnStyle picks the foreground for a data cell: the first column is the
264	// primary identifier (white), the rest are secondary (gray).
265	func (t tableStyles) columnStyle(col int) lipgloss.Style {
266		if col == 0 {
267			return t.primary
268		}
269		return t.cell
270	}
271	
272	// printTable writes headers plus one row per item, columns aligned on the
273	// plain-text widths so ANSI color codes don't throw off the layout (they're
274	// applied after padding). Callers handle the empty case.
275	func printTable[T any](w io.Writer, headers []string, items []T, row func(T) []string) error {
276		st := newTableStyles(w)
277		rows := make([][]string, len(items))
278		for i, it := range items {
279			rows[i] = row(it)
280		}
281		widths := columnWidths(headers, rows)
282	
283		var b strings.Builder
284		writeTableRow(&b, headers, widths, func(int) lipgloss.Style { return st.header }, st)
285		for _, r := range rows {
286			writeTableRow(&b, r, widths, st.columnStyle, st)
287		}
288		if _, err := io.WriteString(w, b.String()); err != nil {
289			return fmt.Errorf("render table: %w", err)
290		}
291		return nil
292	}
293	
294	// printFields writes a single record as aligned "FIELD  value" lines: the
295	// label in header gray, the value in the same primary/secondary color the
296	// list view would give that column.
297	func printFields(w io.Writer, headers, values []string) error {
298		st := newTableStyles(w)
299		labelWidth := 0
300		for _, h := range headers {
301			if n := lipgloss.Width(h); n > labelWidth {
302				labelWidth = n
303			}
304		}
305		var b strings.Builder
306		for i, h := range headers {
307			var v string
308			if i < len(values) {
309				v = values[i]
310			}
311			label := st.style(st.header, h+strings.Repeat(" ", labelWidth-lipgloss.Width(h)))
312			b.WriteString(label)
313			b.WriteString("  ")
314			b.WriteString(st.style(st.columnStyle(i), v))
315			b.WriteByte('\n')
316		}
317		if _, err := io.WriteString(w, b.String()); err != nil {
318			return fmt.Errorf("render fields: %w", err)
319		}
320		return nil
321	}
322	
323	// columnWidths returns the max plain-text width of each column across the
324	// headers and all rows.
325	func columnWidths(headers []string, rows [][]string) []int {
326		widths := make([]int, len(headers))
327		for i, h := range headers {
328			widths[i] = lipgloss.Width(h)
329		}
330		for _, r := range rows {
331			for i, c := range r {
332				if i < len(widths) && lipgloss.Width(c) > widths[i] {
333					widths[i] = lipgloss.Width(c)
334				}
335			}
336		}
337		return widths
338	}
339	
340	// writeTableRow pads each cell to its column width on the plain text, then
341	// styles it — so alignment is computed before any ANSI codes are added.
342	// The final column isn't padded, avoiding trailing whitespace.
343	func writeTableRow(b *strings.Builder, cells []string, widths []int, styleFor func(col int) lipgloss.Style, st tableStyles) {
344		for i, c := range cells {
345			last := i == len(cells)-1
346			padded := c
347			if !last && i < len(widths) {
348				padded = c + strings.Repeat(" ", widths[i]-lipgloss.Width(c))
349			}
350			b.WriteString(st.style(styleFor(i), padded))
351			if !last {
352				b.WriteString("  ")
353			}
354		}
355		b.WriteByte('\n')
356	}
357	
358	// runCoreMutation runs fn against the control plane and renders its outcome
359	// the way the rest of the CLI renders mutations: prints the caller's
360	// ✓-prefixed confirmation on stdout by default, or the wire object as JSON
361	// when --json was passed. fn
362	// returns both so the human line can name the created resource while --json
363	// preserves the full wire model (additive-only: synthesized fields like the
364	// repo remote URL are merged in, nothing is ever omitted). It owns the same
365	// preamble as the other runCore variants: silence usage, build the client,
366	// map API errors to problem-detail messages.
367	func runCoreMutation(cmd *cobra.Command, fn func(ctx context.Context, c *coreapi.Client) (message string, wire any, err error)) error {
368		return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
369			message, wire, err := fn(ctx, c)
370			if err != nil {
371				return err
372			}
373			if jsonRequested(cmd) {
374				return printJSON(cmd.OutOrStdout(), wire)
375			}
376			fmt.Fprintln(cmd.OutOrStdout(), message)
377			return nil
378		})
379	}
380	
381	// activeCoreClient builds the control-plane client for active-context
382	// commands. A package-level seam (production wiring is coreapi.New) so
383	// command-level tests can point the whole command tree at an httptest server
384	// without standing up the auth/context/TLS stack.
385	var activeCoreClient = func(context.Context) (*coreapi.Client, error) { return coreapi.New() }
386	
387	// runCore is the shared base for every active-context control-plane command:
388	// it owns the preamble only — silence usage, build the client, map API
389	// errors — and leaves all rendering to fn. The delete/revoke verbs call it
390	// directly and render their own output; runCoreList, runCoreObject, and
391	// runCoreMutation build on it to add their table/JSON/confirmation
392	// rendering. The client dials the active context's core (coreapi.New); use
393	// runCoreForCluster for commands addressed at a specific cluster.
394	func runCore(cmd *cobra.Command, fn func(ctx context.Context, c *coreapi.Client) error) error {
395		return runCoreClient(cmd, activeCoreClient, fn)
396	}
397	
398	// runCoreForCluster is runCore for resource-provider commands addressed at a
399	// specific cluster (mirror create/remove, mirror collaborators list):
400	// it dials the core that fronts clusterHost — discovered from the cluster's
401	// /.well-known/entire-cluster.json, authenticating with the matching local
402	// context — instead of the active context. So the command works on a cluster in
403	// a federation other than the active login, instead of failing with "unknown
404	// cluster_host". See coreapi.NewForCluster.
405	func runCoreForCluster(cmd *cobra.Command, clusterHost string, fn func(ctx context.Context, c *coreapi.Client) error) error {
406		return runCoreClient(cmd, func(ctx context.Context) (*coreapi.Client, error) {
407			return coreapi.NewForCluster(ctx, clusterHost)
408		}, fn)
409	}
410	
411	// runCoreClient owns the control-plane preamble shared by the active-context
412	// (runCore) and cluster-addressed (runCoreForCluster) variants: silence usage,
413	// opt into plain-HTTP token exchange if requested, build the client via
414	// newClient, run fn, and map API errors. The only difference between the two
415	// variants is which core newClient dials.
416	func runCoreClient(cmd *cobra.Command, newClient func(context.Context) (*coreapi.Client, error), fn func(ctx context.Context, c *coreapi.Client) error) error {
417		cmd.SilenceUsage = true
418		// Opt into plain-HTTP token exchange before the client (and its lazily
419		// built token manager) is constructed — the manager freezes the
420		// setting on first use.
421		if insecureHTTPRequested(cmd) {
422			auth.EnableInsecureHTTP()
423		}
424		client, err := newClient(cmd.Context())
425		if err != nil {
426			return fmt.Errorf("connect to Entire control plane: %w", err)
427		}
428		if err := fn(cmd.Context(), client); err != nil {
429			return renderCoreError(err)
430		}
431		return nil
432	}
433	
434	// markRequired marks one or more flags required, panicking if a name
435	// doesn't exist — that can only happen from a typo at wiring time, never
436	// at runtime, so a panic surfaces the bug immediately rather than letting
437	// a "required" flag silently not be enforced.
438	func markRequired(cmd *cobra.Command, names ...string) {
439		for _, name := range names {
440			if err := cmd.MarkFlagRequired(name); err != nil {
441				panic(fmt.Sprintf("mark flag %q required: %v", name, err))
442			}
443		}
444	}
445	
446	// renderCoreError converts a Core API error into the server's
447	// problem-detail message (so users see "organization name already taken"
448	// rather than ogen's decode-wrapped string), falling back to the raw error
449	// for transport/local failures. It returns a plain error, not a
450	// SilentError: main.go prints plain errors, and runCore has already set
451	// SilenceUsage, so the message reaches the user without a usage dump. (A
452	// SilentError here would be swallowed — main.go skips printing those —
453	// leaving e.g. a 409 conflict with no output.)
